// Read RSS_FEEDS env (comma-separated URLs). Emit one item per feed URL
// so the next HTTP Request fans out.

const feedsEnv = $env.RSS_FEEDS || '';
const feeds = feedsEnv.split(',').map(s => s.trim()).filter(Boolean);

if (feeds.length === 0) {
  throw new Error('RSS_FEEDS env var is empty. Set it to a comma-separated list of feed URLs.');
}

return feeds.map(url => ({ json: { feedUrl: url } }));

// Per-feed-host sliding-window rate limit, opt-in.
// 12 fetches per hour per host (i.e. one every 5 min minimum).
// This blocks an accidentally too-aggressive schedule from hammering a single feed.

if ($env.RATE_LIMIT_ENABLED !== '1') {
  return $input.all();
}

const LIMIT = 12;
const WINDOW_MS = 60 * 60 * 1000;
const MAX_KEYS = 200;

const data = $getWorkflowStaticData('global');
data.rateBuckets = data.rateBuckets || {};
const buckets = data.rateBuckets;
const now = Date.now();

for (const k of Object.keys(buckets)) {
  buckets[k] = (buckets[k] || []).filter(t => now - t < WINDOW_MS);
  if (buckets[k].length === 0) delete buckets[k];
}
if (Object.keys(buckets).length > MAX_KEYS) {
  const oldest = Object.entries(buckets).sort((a, b) => (a[1][0] || 0) - (b[1][0] || 0)).slice(0, 50);
  for (const [k] of oldest) delete buckets[k];
}

const out = [];
for (const item of $input.all()) {
  let host = 'unknown';
  try { host = new URL(item.json.feedUrl).host; } catch (e) { /* keep unknown */ }
  const hits = buckets[host] || [];
  if (hits.length >= LIMIT) {
    // Skip this feed for this cycle. Do not throw because other feeds should keep going.
    continue;
  }
  buckets[host] = [...hits, now];
  out.push(item);
}

return out;

// Lightweight RSS / Atom parser. Extracts items with title / link / guid / pubDate / summary.
// Avoids a heavyweight XML library by tag-walking; works for typical RSS 2.0 + Atom feeds.

const out = [];
for (const item of $input.all()) {
  const xml = String(item.json.data || item.json.body || '');
  const feedUrl = item.json.feedUrl || ($input.first().json.feedUrl) || 'unknown';

  // RSS 2.0: <item>...</item>
  // Atom: <entry>...</entry>
  const itemRegex = /<(item|entry)[\s>][\s\S]*?<\/\1>/gi;
  const matches = xml.match(itemRegex) || [];

  for (const block of matches) {
    const pick = (tag) => {
      const re = new RegExp('<' + tag + '(?:[^>]*)>([\\s\\S]*?)<\\/' + tag + '>', 'i');
      const m = block.match(re);
      return m ? m[1].replace(/<!\[CDATA\[|\]\]>/g, '').trim() : null;
    };
    const linkAttr = (() => {
      const m = block.match(/<link[^>]*href="([^"]+)"/i);
      return m ? m[1] : null;
    })();

    const title = pick('title') || 'Untitled';
    const link = pick('link') || linkAttr || null;
    const guid = pick('guid') || pick('id') || link || (title + ':' + (pick('pubDate') || pick('updated') || ''));
    const pubDate = pick('pubDate') || pick('updated') || pick('published') || null;
    const summary = (pick('description') || pick('summary') || pick('content') || '').replace(/<[^>]+>/g, '').trim().slice(0, 500);

    out.push({ json: { feedUrl, title, link, guid, pubDate, summary } });
  }
}

return out;

// 7-day idempotency window on item guid, opt-in.
// Filters items already seen.

const crypto = require('crypto');

if ($env.IDEMPOTENCY_ENABLED !== '1') {
  return $input.all();
}

const WINDOW_MS = 7 * 24 * 60 * 60 * 1000;
const MAX_KEYS = 50000;

const data = $getWorkflowStaticData('global');
data.seenKeys = data.seenKeys || {};
const seen = data.seenKeys;
const now = Date.now();

for (const k of Object.keys(seen)) {
  if (now - seen[k] > WINDOW_MS) delete seen[k];
}
if (Object.keys(seen).length > MAX_KEYS) {
  const oldest = Object.entries(seen).sort((a, b) => a[1] - b[1]).slice(0, 5000);
  for (const [k] of oldest) delete seen[k];
}

const out = [];
for (const item of $input.all()) {
  const json = item.json || {};
  const baseKey = json.guid || json.link || (json.title + ':' + (json.pubDate || ''));
  const dedupKey = crypto.createHash('sha256').update(String(baseKey)).digest('hex').slice(0, 32);
  if (seen[dedupKey]) continue;
  seen[dedupKey] = now;
  out.push(item);
}

return out;

// Redis variant for clustered n8n:
// const result = await redis.set('rss-idem:' + dedupKey, '1', 'EX', 604800, 'NX');
// if (result === null) continue;

// Normalize each item plus pre-format per-channel post text.

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const title = j.title || 'Untitled';
  const link = j.link || '';
  const summary = j.summary || '';

  const xPost = (title.length > 240 ? title.slice(0, 237) + '...' : title) + (link ? ' ' + link : '');
  const linkedinPost = title + (summary ? '\n\n' + summary : '') + (link ? '\n\n' + link : '');
  const discordPost = (title + '\n' + (summary ? summary + '\n' : '') + (link ? link : '')).slice(0, 1900);

  out.push({
    json: {
      ...j,
      xText: xPost,
      linkedinText: linkedinPost,
      discordText: discordPost,
    },
  });
}
return out;

// Pick enabled social channels from env. Default: empty (post nowhere).
// User must explicitly opt in by setting SOCIAL_CHANNELS.

const chEnv = ($env.SOCIAL_CHANNELS || '').toLowerCase();
const enabled = chEnv.split(',').map(s => s.trim()).filter(Boolean);

const out = [];
for (const item of $input.all()) {
  for (const channel of enabled) {
    out.push({ json: { ...item.json, channel } });
  }
}
return out;

// Aggregate channel results into a single per-cycle summary.
// Reads the items emitted by the three social-channel nodes and tallies success / failure.

const items = $input.all();
const totals = { x: 0, linkedin: 0, discord: 0, total: items.length, errors: 0 };
for (const it of items) {
  const ch = (it.json && it.json.channel) || 'unknown';
  if (totals[ch] != null) totals[ch] += 1;
}
return [{ json: { ...totals, summarizedAt: new Date().toISOString() } }];

// Fallback for any failed channel post (X / LinkedIn / Discord).

const input = $input.first();
const err = (input.json && input.json.error) || input.error || {};
const orig = input.json || {};

return [{
  json: {
    ok: false,
    fallback: true,
    channel: orig.channel || 'unknown',
    title: orig.title || 'unknown',
    link: orig.link || null,
    error: {
      message: err.message || 'unknown error',
      name: err.name || 'SocialPostError',
    },
    receivedAt: new Date().toISOString(),
  },
}];
